@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/adaProduct-metadata-001> ;
            sh:resultMessage "LaserAblation requires ada:spotDiameterMeasured on the analysis." ;
            sh:resultPath ada:spotDiameterMeasured ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "LaserAblation requires ada:spotDiameterMeasured on the analysis." ;
                    sh:minCount 1 ;
                    sh:path ada:spotDiameterMeasured ;
                    sh:severity sh:Warning ] ] .

